    maybeOpening(rx, y, rx - 1, y);
    maybeOpening(rx + rw - 1, y, rx + rw, y);
  }
  for (let x = rx; x < rx + rw; x++) {
    maybeOpening(x, ry, x, ry - 1);
    maybeOpening(x, ry + rh - 1, x, ry + rh);
