  const unique = [];
  const seen = new Set();
  for (const opening of openings) {
    const key = `${opening.x},${opening.y}`;
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(opening);
  }
  return unique.length === 1 ? unique[0] : null;
}

