function canReachNear(start, target, radius = 2) {
  for (let dy = -radius; dy <= radius; dy++) {
    for (let dx = -radius; dx <= radius; dx++) {
      const x = target.x + dx;
      const y = target.y + dy;
      if (isWalkable(x, y) && canReach(start, { x, y })) return true;
    }
  }
  return false;
}

